import{_ as d,o as e,c as o,a5 as a}from"./chunks/framework.CcrBcQWS.js";const k=JSON.parse('{"title":"Sport Client — C++ 예제","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/sdk/cpp/sport-client.md","filePath":"ko/software/sdk/cpp/sport-client.md","lastUpdated":1787021357000}'),s={name:"ko/software/sdk/cpp/sport-client.md"};function i(r,t,c,l,n,p){return e(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="sport-client-—-c-예제" tabindex="-1">Sport Client — C++ 예제 <a class="header-anchor" href="#sport-client-—-c-예제" aria-label="Permalink to &quot;Sport Client — C++ 예제&quot;">​</a></h1><p><strong>소스</strong>: <code>rbq_sdk/cpp/example/src/rbq_sport_client.cpp</code></p><p><strong>SportClient</strong> 명령을 하나씩 로봇에 전송하는 터미널 기반 대화형 애플리케이션입니다.<br> 명령 이름(또는 숫자 ID)을 입력하면 해당 명령이 50 Hz 루프에서 계속 실행됩니다.</p><h2 id="동작-방식" tabindex="-1">동작 방식 <a class="header-anchor" href="#동작-방식" aria-label="Permalink to &quot;동작 방식&quot;">​</a></h2><p>프로그램은 단일 루프로 동작합니다:</p><ol><li><code>stdin</code>에서 한 줄 입력 받기 (<code>list</code>, 명령 이름, 또는 명령 ID).</li><li>현재 <code>test_option</code> 업데이트.</li><li>20 ms 틱마다 해당 <code>SportClient</code> 메서드 호출.</li></ol><p>별도의 제어 스레드 없이 터미널 읽기가 Enter 키 입력까지 블로킹되는 단순한 순차 테스트 방식입니다.</p><h2 id="사전-요구사항" tabindex="-1">사전 요구사항 <a class="header-anchor" href="#사전-요구사항" aria-label="Permalink to &quot;사전 요구사항&quot;">​</a></h2><ul><li>RBQ SDK 빌드 및 설치 완료 — <a href="/RBQ/nightly/ko/software/sdk/cpp/overview.html">C++ SDK 개요</a> 참조.</li><li>로봇 스택이 실행 중(시뮬레이션 또는 하드웨어)이며 동일 네트워크에서 접근 가능해야 합니다.</li></ul><h2 id="빌드" tabindex="-1">빌드 <a class="header-anchor" href="#빌드" aria-label="Permalink to &quot;빌드&quot;">​</a></h2><p><code>rbq_sdk/cpp/example/</code>에서:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>바이너리 위치: <code>bin/rbq_sport_client</code></p><h2 id="실행" tabindex="-1">실행 <a class="header-anchor" href="#실행" aria-label="Permalink to &quot;실행&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_sport_client</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">networkInterfac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 예:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_sport_client</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span></code></pre></div><h2 id="사용-가능한-명령" tabindex="-1">사용 가능한 명령 <a class="header-anchor" href="#사용-가능한-명령" aria-label="Permalink to &quot;사용 가능한 명령&quot;">​</a></h2><p>프롬프트에서 <code>list</code>를 입력하면 전체 명령 목록이 출력됩니다.</p><table tabindex="0"><thead><tr><th>ID</th><th>이름</th><th>호출되는 SportClient 메서드</th></tr></thead><tbody><tr><td>0</td><td><code>damp</code></td><td><code>Damp()</code> — 고댐핑 비상 정지</td></tr><tr><td>1</td><td><code>balance_stand</code></td><td><code>BalanceStand()</code> — 균형 서기</td></tr><tr><td>2</td><td><code>stop_move</code></td><td><code>StopMove()</code> — 제자리 정지</td></tr><tr><td>3</td><td><code>stand_down</code></td><td><code>StandDown()</code> — 엎드리기</td></tr><tr><td>4</td><td><code>recovery_stand</code></td><td><code>RecoveryStand()</code> — 넘어짐 후 일어서기</td></tr><tr><td>5</td><td><code>move</code></td><td><code>Move(0.0, 0.0, 0.5)</code> — 제자리 회전</td></tr><tr><td>6</td><td><code>switch_gait</code></td><td><code>SwitchGait(0)</code> — 기본 보행으로 전환</td></tr><tr><td>7</td><td><code>speed_level</code></td><td><code>SpeedLevel(1)</code> — 속도 레벨 설정</td></tr><tr><td>8</td><td><code>get_state</code></td><td><code>GetState()</code> — FSM / 속도 / 프로세스 상태 출력</td></tr><tr><td>9</td><td><code>recovery_switch</code></td><td><code>SetAutoRecovery(0)</code> — 자동 복구 비활성화</td></tr><tr><td>10</td><td><code>body_height</code></td><td><code>BodyHeight(0.3f)</code> — 몸체 높이 +0.3 m 설정</td></tr><tr><td>11</td><td><code>stand_up</code></td><td><code>StandUp()</code> — 서기 자세로 관절 고정</td></tr><tr><td>12</td><td><code>enter_leftside_gait</code></td><td><code>LeftSideGait(1)</code></td></tr><tr><td>13</td><td><code>exit_leftside_gait</code></td><td><code>LeftSideGait(0)</code></td></tr><tr><td>14</td><td><code>enter_handstand</code></td><td><code>HandStand(1)</code></td></tr><tr><td>15</td><td><code>exit_handstand</code></td><td><code>HandStand(0)</code></td></tr><tr><td>16</td><td><code>front_flip</code></td><td><strong>이 로봇에서는 지원하지 않음</strong></td></tr><tr><td>17</td><td><code>back_flip</code></td><td><strong>이 로봇에서는 지원하지 않음</strong></td></tr><tr><td>18</td><td><code>pose</code></td><td><strong>이 로봇에서는 지원하지 않음</strong></td></tr><tr><td>19</td><td><code>euler</code></td><td><strong>이 로봇에서는 지원하지 않음</strong></td></tr></tbody></table><h2 id="주요-구현-사항" tabindex="-1">주요 구현 사항 <a class="header-anchor" href="#주요-구현-사항" aria-label="Permalink to &quot;주요 구현 사항&quot;">​</a></h2><ul><li><strong>SetNoReply(true)</strong>: <code>SportClient</code>는 <code>SetNoReply(true)</code>로 초기화됩니다. 각 요청을 RPC 응답 대기 없이 DDS 발행 방식으로 전송합니다 — WiFi 환경에서의 고주파 제어에 적합합니다.</li><li><strong>50 Hz 틱</strong>: <code>std::this_thread::sleep_until</code>로 20 ms 루프 주기를 유지합니다.</li><li><strong>에러 카운팅</strong>: <code>res_count</code> 변수가 연속 실패를 누적하여 에러 코드와 함께 출력합니다.</li></ul><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/ko/software/sdk/cpp/sport-client-joy.html">Sport Client (조이스틱)</a></li><li><a href="/RBQ/nightly/ko/software/sdk/cpp/high-level.html">High Level Command</a></li><li><a href="/RBQ/nightly/ko/software/sdk/cpp/overview.html">C++ SDK 개요</a></li></ul>`,22)])])}const g=d(s,[["render",i]]);export{k as __pageData,g as default};
